47	
48	            if (r.Llamadas.Count == 0)
49	            {
50	                var (texto, citas) = Interpretar(r.Texto);
51	                return Resultado(texto, citas);
52	            }
53	
54	            mensajes.Add(new("assistant", r.Texto ?? "", null, r.Llamadas));
55	            foreach (var l in r.Llamadas)
56	            {
57	                var salida = herramientas.Ejecutar(l.Nombre, l.ArgumentosJson);
58	                if (herramientas.Denegado) return Resultado("No tienes permiso para consultar esos datos.", [], true);
59	                mensajes.Add(new("tool", salida, l.Id));
60	            }
61	        }
62	        return Resultado(SinRespuesta, []);
63	    }
64	
65	    // La pregunta es dato: se impide que cierre o abra la etiqueta que la delimita.
66	    static string Neutralizar(string p) => Regex.Replace(p, @"<\s*/?\s*pregunta\s*>", "[etiqueta]", RegexOptions.IgnoreCase);
