5	var builder = WebApplication.CreateBuilder(args);
6	
7	static string ResolverRuta(string? configurada)
8	{
9	    if (!string.IsNullOrWhiteSpace(configurada)) return Path.GetFullPath(configurada);
10	    foreach (var inicio in new[] { AppContext.BaseDirectory, Directory.GetCurrentDirectory() })
11	        for (var d = new DirectoryInfo(inicio); d != null; d = d.Parent)
12	            if (Directory.Exists(Path.Combine(d.FullName, "data", "api"))) return Path.Combine(d.FullName, "data");
13	    return Path.GetFullPath("data");
14	}
15	
16	var ruta = ResolverRuta(builder.Configuration["Datos:Ruta"]);
17	builder.Services.AddSingleton(_ => new Reglamento(Path.Combine(ruta, "reglamento")));
18	builder.Services.AddSingleton(_ => new Datos(Path.Combine(ruta, "api")));
19	builder.Services.AddSingleton<ILlmClient, SinLlmClient>();
20	builder.Services.AddSingleton<Asistente>();
21	
22	var app = builder.Build();
23	
24	// Carga eager: un dato corrupto falla al arrancar, nunca convierte un 400 en 500.
25	app.Services.GetRequiredService<Reglamento>();
26	app.Services.GetRequiredService<Datos>();
27	
28	app.MapGet("/api/salud", () => Results.Json(new { estado = "ok" }));
29	
30	app.MapPost("/api/asistente/preguntar", async (HttpRequest req, Datos datos, IConfiguration cfg, Asistente asistente) =>
31	{
32	    static IResult Error(int codigo, string msg) => Results.Json(new { error = msg }, statusCode: codigo);
33	
34	    JsonDocument doc;
35	    try { doc = await JsonDocument.ParseAsync(req.Body); }
36	    catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }
37	
38	    using (doc)
39	    {
40	        var raiz = doc.RootElement;
41	        if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");
42	
43	        if (!raiz.TryGetProperty("pregunta", out var p) || p.ValueKind != JsonValueKind.String
44	            || string.IsNullOrWhiteSpace(p.GetString()))
45	            return Error(400, "La pregunta es obligatoria.");
46	        if (p.GetString()!.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");
47	
48	        if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
49	            return Error(400, "El usuario es obligatorio.");
50	        if (!u.TryGetProperty("rol", out var r) || r.ValueKind != JsonValueKind.String)
51	            return Error(400, "El rol es obligatorio.");
52	        var rol = r.GetString()!;
53	        if (rol != "estudiante" && rol != "coordinador")
54	            return Error(400, "El rol debe ser 'estudiante' o 'coordinador'.");
55	        if (!u.TryGetProperty("id", out var i) || i.ValueKind != JsonValueKind.String
56	            || string.IsNullOrWhiteSpace(i.GetString()))
